INSERT INTO `sops` (`id`, `jenis`, `isi_sop`, `created_at`, `updated_at`) VALUES
(1, 'peminjaman', '1. Peminjaman harus menggunakan seragam Sekolah.\r\n2. Peminjam wajib membawa ID Card/Kartu Pelajar.\r\n3. Pilih alat dan barang yang ingin dipinjam dan pastikan menuliskan alasan peminjaman dengan jelas.\r\n4. Peminjaman selain BARANG UMUM harus menggunakan Surat Peminjaman.\r\nContoh barang umum: Kunci Ruangan, LCD Projector, Kabel, dll\r\n5. Jika memilih barang tercatat, setelah mengisi form dapat menunggu verifikasi oleh Tim Teknisi sebelum surat dapat dicetak.\r\n6. Ketika akan mengambil dan mengembalikan barang tercatat wajib membawa Surat Peminjaman dan ID Card/Kartu Pelajar.\r\n7. Pengembalian barang umum dapat dilakukan di Website Layanan Peminjaman Barang.\r\n\r\nTerima Kasih ^_^', '2026-04-23 05:03:02', '2026-04-23 05:11:24'),
(2, 'pengembalian', '1. Pengembalian barang harus menggunakan seragam Sekolah.\r\n2. Peminjam wajib membawa ID Card/Kartu Pelajar\r\n3. Pengembalian barang umum dapat dilakukan langsung di Website.\r\n4. Pengembalian barang tercatat wajib membawa surat dan menemui Tim Teknisi/Koordinator Teknisi\r\n5. Barang yang dikembalikan harus dalam kondisi baik dan lengkap.\r\n6. Jika terdapat ketidaksesuaian kondisi barang seperti sebelum dipinjam, diwajibkan bertanggung jawab.\r\n\r\nTerima Kasih ^_^', '2026-04-23 05:11:09', '2026-04-23 05:11:09');
